// spec: specs/recommendations-similar-businesses.md (1.5) · кейс: .qa/tests/recommendations-similar-businesses/SIMILAR-05.md
// Регресс #97caf3: блок есть в объявлениях и с длинным, и с коротким описанием. Прод, только просмотр.
import { test, expect } from '@playwright/test';
import { blockWrites, openListing, cardIds, readCatalog } from './similar.helpers';

test.use({ serviceWorkers: 'block' });

test('Блок есть в объявлении с длинным и с коротким описанием #02706d #97caf3 @desktop @prod-safe', async ({ page }) => {
  await blockWrites(page);
  await page.goto('/');
  const catalog = await readCatalog(page);
  const byLen = [...catalog].sort((x, y) => (y.description || '').length - (x.description || '').length);
  const long = byLen[0];
  const short = byLen.filter((b) => (b.description || '').trim().length > 0).at(-1)!;
  expect((long.description || '').length, 'есть объявление с длинным описанием').toBeGreaterThan(1000);
  expect((short.description || '').length, 'есть объявление с коротким описанием').toBeLessThan(60);

  for (const biz of [long, short]) {
    await openListing(page, biz.id);
    const ids = await cardIds(page);
    expect(ids.length, `карточки в блоке (${(biz.description || '').length} симв.)`).toBeGreaterThan(0);
    expect(ids.length).toBeLessThanOrEqual(12);
    expect(ids).not.toContain(biz.id);
  }
});
